    return Math.min(MANGA_DIRECTORY_VISUAL.quickMaxListHeight, Math.max(MANGA_DIRECTORY_VISUAL.gridHeight, MANGA_DIRECTORY_VISUAL.namedMinHeight) * mangaDirectoryScale(fontScale));
}
export function mangaDirectoryFullFlowFooter(viewportHeight: number, fontScale: number, safeTop: number, safeBottom: number, footerHeight: number): boolean {
    if (!Number.isFinite(viewportHeight) || viewportHeight <= 0)
        return false;
    const scale = mangaDirectoryScale(fontScale);
    const headerBottom = Math.max(0, safeTop) + MANGA_DIRECTORY_VISUAL.headerSafeGap + mangaDirectoryHeaderHeight(scale);
    const footerTop = viewportHeight - Math.max(0, safeBottom) - MANGA_DIRECTORY_VISUAL.footerBottom - Math.max(0, footerHeight);
    const minimum = Math.max(MANGA_DIRECTORY_VISUAL.namedMinHeight, MANGA_DIRECTORY_VISUAL.namedLineHeight * scale + MANGA_DIRECTORY_VISUAL.namedPaddingY * 2 + MANGA_DIRECTORY_VISUAL.gridBorder);
    return footerTop - headerBottom < minimum;
}
export function mangaDirectoryQuickFlowGaps(): number {
    return MANGA_DIRECTORY_VISUAL.quickGap * 2;
}
export function mangaDirectoryPositionStacked(contentWidth: number, fontScale: number, position: string): boolean {
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
        return false;
    const scale = mangaDirectoryScale(fontScale);
    const pageEm = Array.from(position).reduce((sum: number, character: string): number => sum + (character.charCodeAt(0) < 128 ? MANGA_DIRECTORY_VISUAL.numericDigitWidthEm : 1), 0);
    const reserved = (MANGA_DIRECTORY_VISUAL.positionMinimumTitleEm * MANGA_DIRECTORY_VISUAL.positionFontSize + pageEm * MANGA_DIRECTORY_VISUAL.positionPageFontSize) * scale + MANGA_DIRECTORY_VISUAL.positionRowGap + MANGA_DIRECTORY_VISUAL.positionPaddingX * 2;
    return contentWidth < reserved;
}
export function mangaDirectoryHeaderHeight(fontScale: number): number {
    return Math.max(MANGA_DIRECTORY_VISUAL.headerHeight, MANGA_DIRECTORY_VISUAL.headerLineHeight * mangaDirectoryScale(fontScale) + MANGA_DIRECTORY_VISUAL.headerPadding * 2 + MANGA_DIRECTORY_VISUAL.borderWidth * 2);
}
export function mangaDirectoryContentTop(fontScale: number): number {
    return mangaDirectoryHeaderHeight(fontScale) + MANGA_DIRECTORY_VISUAL.contentTop - MANGA_DIRECTORY_VISUAL.headerHeight;
}
export function mangaDirectoryFooterStacked(contentWidth: number, fontScale: number, position: string): boolean {
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
        return false;
    const pageEm = Array.from(position).reduce((sum: number, character: string): number => sum + (character.charCodeAt(0) < 128 ? MANGA_DIRECTORY_VISUAL.numericDigitWidthEm : 1), 0);
    const reserved = (4 + pageEm) * MANGA_DIRECTORY_VISUAL.footerMetaFontSize * mangaDirectoryScale(fontScale) + MANGA_DIRECTORY_VISUAL.footerMinimumTitleEm * MANGA_DIRECTORY_VISUAL.footerTitleFontSize * mangaDirectoryScale(fontScale) + MANGA_DIRECTORY_VISUAL.footerGap * 2 + (MANGA_DIRECTORY_VISUAL.footerPaddingX + MANGA_DIRECTORY_VISUAL.borderWidth) * 2;
    return contentWidth < reserved;
}
export function mangaDirectoryFooterHeight(fontScale: number, contentWidth: number = 0, position: string = ''): number {
    const scale = mangaDirectoryScale(fontScale);
    if (!mangaDirectoryFooterStacked(contentWidth, scale, position))
        return mangaDirectoryLineBox(MANGA_DIRECTORY_VISUAL.footerHeight, MANGA_DIRECTORY_VISUAL.footerTitleLineHeight, (MANGA_DIRECTORY_VISUAL.footerPaddingY + MANGA_DIRECTORY_VISUAL.borderWidth) * 2, scale);
    const inner = Math.max(1, contentWidth - (MANGA_DIRECTORY_VISUAL.footerPaddingX + MANGA_DIRECTORY_VISUAL.borderWidth) * 2);
    const pageEm = Array.from(position).reduce((sum: number, character: string): number => sum + (character.charCodeAt(0) < 128 ? MANGA_DIRECTORY_VISUAL.numericDigitWidthEm : 1), 0);
    const pageLines = position.length === 0 ? 0 : Math.max(1, Math.ceil(pageEm * MANGA_DIRECTORY_VISUAL.footerMetaFontSize * scale / inner));
    return Math.max(MANGA_DIRECTORY_VISUAL.footerHeight, (MANGA_DIRECTORY_VISUAL.footerMetaLineHeight * (1 + pageLines) + MANGA_DIRECTORY_VISUAL.footerTitleLineHeight) * scale + MANGA_DIRECTORY_VISUAL.footerStackGap * (pageLines > 0 ? 2 : 1) + (MANGA_DIRECTORY_VISUAL.footerPaddingY + MANGA_DIRECTORY_VISUAL.borderWidth) * 2);
}
export function mangaDirectoryLabelsFit(kind: string, fontScale: number, contentWidth: number, numberLengths: number[], accessoryWidth: number = 0): boolean {
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
        return true;
    return numberLengths.every((length: number): boolean => (length * MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.numericDigitWidthEm + (kind === 'parts' ? MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.partLabelWidthEm : 0)) * mangaDirectoryScale(fontScale) + (MANGA_DIRECTORY_VISUAL.gridPaddingX + MANGA_DIRECTORY_VISUAL.gridBorder) * 2 + Math.max(0, accessoryWidth) <= contentWidth);
}
export function mangaDirectoryColumns(kind: string, hasMiddle: boolean, narrow: boolean, fontScale: number, contentWidth: number, numberLengths: number[], accessoryWidth: number = 0): number {
    if (kind === 'named')
        return 1;
    const preferred = kind === 'numeric' ? (narrow ? 3 : 4) : hasMiddle ? 3 : narrow ? 2 : 4;
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
        return preferred;
    const longest = numberLengths.reduce((length: number, value: number): number => Math.max(length, value), 0);
    const text = (longest * MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.numericDigitWidthEm + (kind === 'parts' ? MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.partLabelWidthEm : 0)) * mangaDirectoryScale(fontScale);
    const minimum = Math.max(MANGA_DIRECTORY_VISUAL.gridHeight, text + MANGA_DIRECTORY_VISUAL.gridPaddingX * 2 + MANGA_DIRECTORY_VISUAL.gridBorder * 2 + Math.max(0, accessoryWidth));
    const capacity = Math.max(1, Math.min(preferred, Math.floor((contentWidth + MANGA_DIRECTORY_VISUAL.gridGap) / (minimum + MANGA_DIRECTORY_VISUAL.gridGap))));
    return kind === 'parts' ? (hasMiddle ? (capacity >= 3 ? 3 : 1) : capacity >= 4 ? 4 : capacity >= 2 ? 2 : 1) : capacity;
}

