        if (this.choiceEnabled && (this.visible || this.openOnMount))
            this.openSheet();
    }
    aboutToDisappear(): void {
        this.mounted = false;
        this.sheetVisible = false;
        this.closed = true;
        this.openEpoch += 1;
    }
    @Builder
    private emptyTrigger() { }
    private effectiveScheme(): string {
        return typeof this.scheme === 'string' && this.scheme.length > 0 ? this.scheme : this.appThemeScheme;
    }
    private choiceOptions(): string[] {
        return Array.isArray(this.options) ? this.options : [];
    }
    private onTokenChanged(): void {
        if (!this.mounted)
            return;
        const wasOpen = this.sheetVisible && !this.closed;
        this.closeCurrent(false);
        if (this.choiceEnabled && (this.visible || wasOpen || this.openOnMount))
            this.openSheet();
    }
    private onChoiceEnabledChanged(): void {
        if (!this.mounted)
            return;
        if (!this.choiceEnabled)
            this.closeCurrent(true);
    }
    private onOptionsChanged(): void {
        const signature = JSON.stringify(this.choiceOptions());
        if (signature === this.optionSignature)
            return;
        this.optionSignature = signature;
        if (this.mounted && !this.closed)
            this.closeCurrent(true);
    }
    private onVisibleChanged(): void {
        if (!this.mounted || this.lastVisible === this.visible)
            return;
        this.lastVisible = this.visible;
        if (this.visible && this.choiceEnabled)
            this.openSheet();
        else
            this.closeCurrent(true);
    }
    private openSheet(): void {
        if (!this.mounted || this.choiceEnabled !== true || typeof this.selectionToken !== 'string' || this.selectionToken.length === 0)
            return;
        if (this.sheetVisible && !this.closed)
            return;
        this.openEpoch += 1;
        this.closed = false;
        this.sheetVisible = true;
    }
    private owns(token: string, epoch: number): boolean {
        return this.mounted && this.choiceEnabled && !this.closed && this.sheetVisible &&
            token.length > 0 && token === this.selectionToken && epoch === this.openEpoch;
    }
    private closeCurrent(notify: boolean): void {
        if (this.closed)
            return;
        const token = this.selectionToken;
        this.closed = true;
        this.sheetVisible = false;
        this.openEpoch += 1;
        if (notify && this.mounted)
            this.onDismiss(token);
    }
    private dismissFor(token: string, epoch: number): void {
        if (!this.owns(token, epoch))
            return;
        this.closeCurrent(true);
    }
    private choose(index: number, option: string, token: string, epoch: number): void {
        const options = this.choiceOptions();
        if (!this.owns(token, epoch) || index < 0 || index >= options.length)
            return;
        const chosen = options[index];
        if (chosen === undefined || chosen !== option)
            return;
        this.closed = true;
        this.sheetVisible = false;
        this.openEpoch += 1;
        this.onSelect(index, chosen, token);
    }
    build() {
        if (this.openOnMount) {
                .width<
      >('100%').height<
      >('100%').zIndex<
      >(30)
                .onClick<
      >((): void => this.openSheet())
                .bindSheet<
      >(this.sheetVisible && this.choiceEnabled, this.sheetBuilder(this.selectionToken, this.openEpoch), this.sheetOptions(this.selectionToken, this.openEpoch));
        }
        else {
                .constraintSize<
      >({ maxWidth: '100%' })
                .onClick<
      >((): void => this.openSheet())
                .bindSheet<
      >(this.sheetVisible && this.choiceEnabled, this.sheetBuilder(this.selectionToken, this.openEpoch), this.sheetOptions(this.selectionToken, this.openEpoch));
        }
    }
    private sheetBuilder(token: string, epoch: number): CustomBuilder {
        return (): void => this.sheetContent(token, epoch);
    }
    private sheetOptions(token: string, epoch: number): SheetOptions {
        const scheme = this.effectiveScheme();
        return {
            height: this.sheetHeight(), width: '100%', preferType: SheetType.BOTTOM,
            dragBar: false, showClose: false,
            backgroundColor: mangaDirectoryColor('surface', scheme),
            radius: { topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 },
            maskColor: mangaDirectoryColor('scrim', scheme), enableOutsideInteractive: false,
            onDisappear: (): void => this.dismissFor(token, epoch),
        };
    }
    private viewportHeightNow(): number {
        const metrics = this.currentMetrics();
        const measured = this.viewportHeight > 0 ? this.viewportHeight : metrics.windowRect.height;
        return Math.max(1, measured);
    }
    private currentMetrics() {
        const metrics = ReaderWindowCoordinator.metrics();
        return this.readerWindowMetricsRevision === metrics.revision ? metrics : ReaderWindowCoordinator.metrics();
    }
    private sheetHeight(): number {
        const metrics = this.currentMetrics();
        const safeBottom = readerInteractiveSafeBottom(metrics);
        const available = this.viewportHeightNow();
        const usable = Math.max(1, available - safeBottom);
        const maximum = Math.max(1, Math.min(usable, Math.round(usable * 0.78)));
        const rowHeight = this.rowHeight();
        const natural = MANGA_SHEET.handleZone + MANGA_SHEET.closeSize + MANGA_SHEET.quickHeaderPaddingBottom +
            this.choiceOptions().length * rowHeight + MANGA_SHEET.quickPaddingBottom + safeBottom;
        return Math.max(1, Math.min(maximum, natural));
    }
    private sheetBodyHeight(): number {
        const safeBottom = readerInteractiveSafeBottom(this.currentMetrics());
        const usable = this.sheetHeight() - safeBottom - MANGA_SHEET.handleZone - MANGA_SHEET.closeSize -
            MANGA_SHEET.quickHeaderPaddingBottom - MANGA_SHEET.quickPaddingBottom;
        return Math.max(0, Math.min(this.choiceOptions().length * this.rowHeight(), usable));
    }
    private rowHeight(): number {
        return resolveReaderChoiceSpec(this.rowSpec()).height;
    }
    private rowSpec(): 'settings-phone' | 'settings-tablet' | 'source-group-option' | 'default-option' | 'directory-offline-option' {
        if (this.variant === 'settings-phone')
            return 'settings-phone';
        if (this.variant === 'settings-tablet')
            return 'settings-tablet';
        if (this.variant === 'source-group')
            return 'source-group-option';
        if (this.variant === 'directory-offline')
            return 'directory-offline-option';
        return 'default-option';
    }
    @Builder
    private sheetContent(token: string, epoch: number) {
            .width<
    >('100%').height<
    >(this.sheetHeight())
            .padding<
    >({ bottom: readerInteractiveSafeBottom(this.currentMetrics()) + MANGA_SHEET.quickPaddingBottom })
            .backgroundColor<
    >(mangaDirectoryColor('surface', this.effectiveScheme()))
            .shadow<
    >({ radius: 48, color: this.effectiveScheme() === 'night' ? '#66000000' : '#33000000', offsetX: 0, offsetY: -16 })
            .borderRadius<
    >({ topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 });
    }
}

import { ReaderChoiceSpec, ReaderChoiceSpecId, resolveReaderChoiceSpec } from './ReaderChoiceSpecs';
import { readerAppColor } from './ReaderThemeRegistry';
import type { ReaderTextStyle } from './ReaderTypography';
class ReaderChoiceLabelModifier implements AttributeModifier<TextAttribute> {
    private id: ReaderChoiceSpecId;
    private selected: boolean;
    constructor(id: ReaderChoiceSpecId, selected: boolean) {
        this.id = id;
        this.selected = selected;
    }
    applyNormalAttribute(instance: TextAttribute): void {
        const spec = resolveReaderChoiceSpec(this.id);
        const text = this.selected ? spec.selectedText : spec.text;
        instance.fontFamily(text.fontFamily);
        const weight = this.selected ? spec.selectedWeight : text.fontWeight;
        if (spec.variableWeight)
            instance.fontWeight(weight, { enableVariableFontWeight: true });
        else
            instance.fontWeight(weight);
        instance.fontSize(text.fontSizeFp);
        if (text.lineHeightFp !== undefined)
            instance.lineHeight(text.lineHeightFp);
        if (spec.textAlignStart)
            instance.textAlign(TextAlign.Start);
        if (spec.ellipsis)
            instance.textOverflow({ overflow: TextOverflow.Ellipsis });
    }
}
@Component
export struct ReaderChoiceRow extends   {
    constructor(?: {
        specId?: ReaderChoiceSpecId;
        label?: string;
        selected?: boolean;
        showDivider?: boolean;
        scheme?: string;
        availableWidth?: number;
        chevronAngle?: number;
        actionEnabled?: boolean;
        onChoose?: (value: string) => void;
        private mounted?: boolean;
    }, ?: ) { }
    @Prop
    specId: ReaderChoiceSpecId = 'default-option';
    @Prop
    label: string = '';
    @Prop
    selected: boolean = false;
    @Prop
    showDivider: boolean = false;
    @Prop
    scheme: string = 'day';
    @Prop
    availableWidth: number = 0;
    @Prop
    chevronAngle: number = 0;
    @Prop
    actionEnabled: boolean = true;
    onChoose: (value: string) => void = (): void => { };
    private mounted: boolean = false;
    aboutToAppear(): void { this.mounted = true; }
    aboutToDisappear(): void { this.mounted = false; }
    build() {
        .width<
    >('100%').height<
    >(this.spec().height);
    }
    @Builder
    private normalRow() {
        .width<
    >('100%').height<
    >(this.rowHeight())
            .padding<
    >({ left: this.spec().padding, right: this.spec().padding })
            .alignItems<
    >(VerticalAlign.Center).borderRadius<
    >(this.spec().radius)
            .backgroundColor<
    >(this.rowBackground())
            .enabled<
    >(this.actionEnabled).accessibilityText<
    >(this.accessibilityLabel())
            .onClick<
    >((): void => this.choose());
    }
    @Builder
    private positionedRow() {
        .width<
    >('100%').height<
    >(this.rowHeight())
            .backgroundColor<
    >(this.rowBackground()).enabled<
    >(this.actionEnabled)
            .accessibilityText<
    >(this.accessibilityLabel()).onClick<
    >((): void => this.choose());
    }
    private spec(): ReaderChoiceSpec { return resolveReaderChoiceSpec(this.specId); }
    private textStyle(): ReaderTextStyle { return this.selected ? this.spec().selectedText : this.spec().text; }
    private rowHeight(): number { return this.spec().height - (this.showDivider ? this.spec().dividerHeight : 0); }
    private textColor(): ResourceColor { return readerAppColor(this.selected ? this.spec().selectedTextRole : this.spec().textRole, this.scheme); }
    private rowBackground(): ResourceColor {
        return this.selected && this.spec().selectedBackground !== undefined ?
            readerAppColor(this.spec().selectedBackground!, this.scheme) : Color.Transparent;
    }
    private hasIcon(): boolean { return this.spec().showIcon === 'always' || (this.spec().showIcon === 'selected' && this.selected); }
    private icon(): Resource { return $r(this.scheme === 'night' ? this.spec().iconNight : this.spec().iconDay); }
    private accessibilityLabel(): string { return this.specId === 'appearance-library' ? `${this.label}${this.selected ? '，已选择' : ''}` : this.label; }
    private choose(): void { if (this.mounted && this.actionEnabled)
        this.onChoose(this.label); }
}

