private downloadChoiceToken(id: string): string {
    const optionsIdentity = id === 'source' ? JSON.stringify(this.sourceChoices()) :
        id === 'range-book' ? JSON.stringify(this.actionBooks().map((book: DownloadBookView): string => `${book.key}:${book.title}`)) : '';
    return `${this.presentationGeneration}:${this.mountedIdentity}:${this.detailKey}:${this.managing}:${this.sheet}:${this.overlayChromeRequestGeneration}:${id}:${optionsIdentity}`;
}

private acceptDownloadChoice(token: string, id: string): boolean {
    return this.presentationIsCurrent() && token === this.downloadChoiceToken(id) && this.confirmation.length === 0;
}

@Builder
private sheetOverlay() {
    .width<
    >(0).height<
    >(0).hitTestBehavior<
    >(HitTestMode.None)
        .bindSheet<
    >(this.sheet.length > 0 && this.confirmation.length === 0, this.downloadSheetBuilder(this.presentationGeneration, this.sheet, this.overlayChromeRequestGeneration), this.downloadSheetOptions(this.presentationGeneration, this.sheet, this.overlayChromeRequestGeneration));
}

private downloadSheetBuilder(generation: number, sheetId: string, overlayEpoch: number): CustomBuilder {
    return (): void => this.sheetContent(this.sheetChromeOverflow(), generation, sheetId, overlayEpoch);
}

private downloadSheetOptions(generation: number, sheetId: string, overlayEpoch: number): SheetOptions {
    return { height: SheetSize.FIT_CONTENT, width: '100%', preferType: SheetType.BOTTOM, dragBar: false, showClose: false,
        backgroundColor: mangaDirectoryColor('surface', this.appThemeScheme),
        radius: { topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 },
        maskColor: mangaDirectoryColor('scrim', this.appThemeScheme), enableOutsideInteractive: false,
        onDisappear: (): void => this.dismissDownloadSheet(generation, sheetId, overlayEpoch) };
}

private dismissDownloadSheet(generation: number, sheetId: string, overlayEpoch: number): void {
    if (sheetId.length > 0 && this.presentationIsCurrent(generation) && this.sheet === sheetId &&
        this.confirmation.length === 0 && overlayEpoch === this.overlayChromeRequestGeneration)
        this.sheet = '';
}

@Builder
private sheetContent(wholeDocument: boolean, ownerGeneration: number = this.presentationGeneration, sheetId: string = this.sheet, overlayEpoch: number = this.overlayChromeRequestGeneration) {
    .width<
    >('100%').constraintSize<
    >({ maxHeight: this.sheetMaxHeight() })
        .backgroundColor<
    >(mangaDirectoryColor('surface', this.appThemeScheme))
        .borderRadius<
    >({ topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 })
        .clip<
    >(true).shadow<
    >({ radius: 48, color: this.appThemeScheme === 'night' ? '#66000000' : '#33000000', offsetX: 0, offsetY: -16 });
}

@Builder
private sheetDocument(wholeDocument: boolean, ownerGeneration: number = this.presentationGeneration, sheetId: string = this.sheet, overlayEpoch: number = this.overlayChromeRequestGeneration) {
    .width<
    >('100%');
}

private sheetChromeHeight(): number {
    const grip = MANGA_SHEET.handleZone;
    const title = Math.max(MANGA_SHEET.closeSize + MANGA_SHEET.quickHeaderPaddingBottom, this.sheetTitleMeasuredHeight);
    const footer = this.sheetHasFooter() ? Math.max(this.sheetFooterMeasuredHeight, this.textControlHeight(DOWNLOAD_VISUAL.buttonHeight, DOWNLOAD_VISUAL.controlLineHeight, DOWNLOAD_VISUAL.buttonPaddingY * 2) + (this.sheet === 'settings' ? DOWNLOAD_VISUAL.storageFooterTop : DOWNLOAD_VISUAL.sheetFooterTop) +
        this.sheetFooterBottomInset() + (this.sheet === 'settings' ? 0 : DOWNLOAD_VISUAL.borderWidth)) : 0;
    return grip + title + footer;
}

private syncOverlayChrome(): void {
    if (!this.presentationIsCurrent())
        return;
    const identity = this.mountedIdentity;
    const generation = this.presentationGeneration;
    const requestGeneration = ++this.overlayChromeRequestGeneration;
    void Promise.resolve().then((): void => {
        if (!this.presentationIsCurrent(generation) || this.mountedIdentity !== identity ||
            requestGeneration !== this.overlayChromeRequestGeneration)
            return;
        if (this.sheet.length > 0 || this.confirmation.length > 0) {
            const visual = downloadOverlayChromeStyle(this.appThemeScheme, this.sheet.length > 0 && this.confirmation.length === 0, 1);
            const style = new ReaderWindowChromeStyle(visual.underlayColor, visual.tone, visual.contentColor);
            style.navigationUnderlayColor = visual.navigationUnderlayColor;
            style.navigationContentColor = visual.navigationContentColor;
            ReaderWindowCoordinator.requestOverlayChrome(style);
            this.overlayChromeClaimed = true;
        }
        else if (this.overlayChromeClaimed) {
            ReaderWindowCoordinator.requestAppChrome();
            this.overlayChromeClaimed = false;
        }
    });
}

